import{_ as a,c as s,a as t,o as e}from"./app-C1s5HV2F.js";const p={};function o(l,n){return e(),s("div",null,n[0]||(n[0]=[t(`<h1 id="basic-arithmetic" tabindex="-1"><a class="header-anchor" href="#basic-arithmetic"><span>Basic Arithmetic</span></a></h1><p>OpenMadness makes performing common math operations on arrays easier and more efficient. Instead of performing calculations one by one, OM lets you apply operations to entire arrays at once.</p><p>When you use an arithmetic method like <code>add()</code> or <code>multiply()</code> on an array, it applies that operation to every corresponding number in the array. If you add a single number (a scalar), it&#39;s added to every element in the array.</p><p>For example, if you have an array of daily sales for each day using this data:</p><table><thead><tr><th>Day</th><th>Sales</th><th>Marketing Spend</th></tr></thead><tbody><tr><td>Day 1</td><td>100</td><td>10</td></tr><tr><td>Day 2</td><td>150</td><td>25</td></tr><tr><td>Day 3</td><td>200</td><td>40</td></tr></tbody></table><p>you can easily perform the following operations on it:</p><ol><li>Create arrays for daily sales and marketing spend:</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> omArray <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Create arrays</span></span>
<span class="line"><span class="token keyword">const</span> dailySales <span class="token operator">=</span> <span class="token function">omArray</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">150</span><span class="token punctuation">,</span> <span class="token number">200</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> marketingSpend <span class="token operator">=</span> <span class="token function">omArray</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">,</span> <span class="token number">40</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Daily Sales:&quot;</span><span class="token punctuation">,</span> dailySales<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [100, 150, 200]</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Marketing Spend:&quot;</span><span class="token punctuation">,</span> marketingSpend<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [10, 25, 40]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>To calculate the total revenue by adding the marketing spend to each sale:</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token comment">// Add two arrays (element-wise)</span></span>
<span class="line"><span class="token keyword">const</span> totalRevenue <span class="token operator">=</span> dailySales<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>marketingSpend<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Total Revenue (Sales + Spend):&quot;</span><span class="token punctuation">,</span> totalRevenue<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [110, 175, 240]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li>To calculate the net sales by subtracting the marketing spend from each sale:</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">const</span> netSales <span class="token operator">=</span> dailySales<span class="token punctuation">.</span><span class="token function">subtract</span><span class="token punctuation">(</span>marketingSpend<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Net Sales (Sales - Spend):&quot;</span><span class="token punctuation">,</span> netSales<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [90, 125, 160]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>To Calculate the sales after each day increased using this data:</li></ol><table><thead><tr><th>Day</th><th>Sales Increase</th></tr></thead><tbody><tr><td>Day 1</td><td>50</td></tr><tr><td>Day 2</td><td>75</td></tr><tr><td>Day 3</td><td>20</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">const</span> salesIncrease <span class="token operator">=</span> dailySales<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">50</span><span class="token punctuation">,</span> <span class="token number">75</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Sales after increase:&quot;</span><span class="token punctuation">,</span> salesIncrease<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [140, 200, 180 ]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li>To calculate the doubled sales by multiplying each sale by 2:</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">const</span> doubledSales <span class="token operator">=</span> dailySales<span class="token punctuation">.</span><span class="token function">multiply</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Doubled Sales:&quot;</span><span class="token punctuation">,</span> doubledSales<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [280, 400, 360]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="6"><li>To calculate the sales ratio by dividing each sale by the corresponding marketing spend:</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">const</span> salesRatio <span class="token operator">=</span> dailySales<span class="token punctuation">.</span><span class="token function">divide</span><span class="token punctuation">(</span>marketingSpend<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Sales Ratio (Sales / Spend):&quot;</span><span class="token punctuation">,</span> salesRatio<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [10, 6, 5]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div>`,19)]))}const i=a(p,[["render",o]]),u=JSON.parse('{"path":"/tutorials/fundamentals/basic-arithmetics.html","title":"Basic Arithmetic","lang":"en-US","frontmatter":{"lang":"en-US","title":"Basic Arithmetic","description":"Learn how to perform basic arithmetic operations in OpenMadness library"},"headers":[],"git":{"updatedTime":1752233059000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":2,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"0acba5225b3b7241742c11f2eb31ec2dcd6ddd05","time":1752233059000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"Updated content"},{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"tutorials/fundamentals/basic-arithmetics.md"}');export{i as comp,u as data};
